package com.pixilife.android;import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.widget.*;
public class PersonalityActivity extends Activity {private PersonalityManager m;@Override public void onCreate(Bundle b){super.onCreate(b);m=new PersonalityManager(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(30,30,30,30);r.setBackgroundColor(Color.rgb(7,11,17));TextView h=new TextView(this);h.setText("PERSONALIDAD DE PIXI\nActual: "+m.current());h.setTextColor(Color.WHITE);h.setTextSize(24);r.addView(h);for(String x:new String[]{"tranquilo","divertido","serio","tecnico"}){Button v=new Button(this);v.setText(x);v.setOnClickListener(z->{m.set(x);new MemoryManager(this).saveMemory(MemoryManager.SYSTEM_MEMORY,m.profile(),true);Intent i=new Intent(this,ConversationService.class).setAction(ConversationService.ACTION_PERSONALITY).putExtra("text",x);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);h.setText("PERSONALIDAD DE PIXI\nActual: "+x);});r.addView(v);}Switch evolution=new Switch(this);evolution.setText("Evolución lenta");evolution.setTextColor(Color.WHITE);evolution.setChecked(m.evolution());evolution.setOnCheckedChangeListener((v,on)->m.evolution(on));r.addView(evolution);Button reset=new Button(this);reset.setText("Restaurar personalidad original");reset.setOnClickListener(v->{m.reset();recreate();});r.addView(reset);setContentView(r);}}
